import type { ItemStack } from '../types'

/** Vanilla lapis cost per enchant row: top=1, middle=2, bottom=3. */
export function lapisCostForEnchantRow(rowIndex: number): number {
  return rowIndex + 1
}

export function isLapisItem(item: ItemStack | null | undefined): boolean {
  if (!item) return false
  if (item.name && /lapis/i.test(item.name)) return true
  // Legacy id: dye + meta 4
  if (item.type === 351 && (item.metadata ?? 0) === 4) return true
  return false
}

export function getLapisCountInSlot(item: ItemStack | null | undefined): number {
  if (!item || !isLapisItem(item)) return 0
  return item.count
}

/** Human-readable blocker when a row looks available from server props but cannot be used. */
export function getEnchantRowBlockReason(opts: {
  level: number
  rowIndex: number
  targetItem: ItemStack | null | undefined
  lapisItem: ItemStack | null | undefined
  requireLapis: boolean
}): string | null {
  const { level, rowIndex, targetItem, lapisItem, requireLapis } = opts
  if (level <= 0) return null
  if (!targetItem) return 'Place an item to enchant'
  if (!requireLapis) return null
  const need = lapisCostForEnchantRow(rowIndex)
  const have = getLapisCountInSlot(lapisItem)
  if (have === 0) return 'Place Lapis Lazuli in the slot'
  if (have < need) return `Need ${need} Lapis Lazuli (${have} in slot)`
  return null
}
