  1: 'Fire Protection',
  2: 'Feather Falling',
  3: 'Blast Protection',
  4: 'Projectile Protection',
  5: 'Respiration',
  6: 'Aqua Affinity',
  7: 'Thorns',
  8: 'Depth Strider',
  9: 'Frost Walker',
  10: 'Binding Curse',
  16: 'Sharpness',
  17: 'Smite',
  18: 'Bane of Arthropods',
  19: 'Knockback',
  20: 'Fire Aspect',
  21: 'Looting',
  22: 'Sweeping Edge',
  32: 'Efficiency',
  33: 'Silk Touch',
  34: 'Unbreaking',
  35: 'Fortune',
  48: 'Power',
  49: 'Punch',
  50: 'Flame',
